void process_postgresql_packet(struct packet *packet) {
    if (packet->source == CLIENT) {
        guint32 length = tvb_get_ntohl(packet->tvb, 0);

        if (length < MIN_PACKET_SIZE) {
            return;
        }

        char *user = extract_user(packet->tvb);
        char *database = extract_database(packet->tvb);

        struct session *session = find_session(packet);
        if (!session) {
            session = create_session();
            session->user = user;
            session->database = database;
            session->status = CONNECTION_STARTED;
            add_session(session);
        } else {
            g_free(session->user);
            g_free(session->database);
            session->user = user;
            session->database = database;

            guint8 auth_type = tvb_get_guint8(packet->tvb, 4);
            if (auth_type == AUTH_MD5) {
                session->status = AUTH_MD5_SENT;
            } else if (auth_type == AUTH_CLEARTEXT) {
                session->status = AUTH_CLEARTEXT_SENT;
            }
        }
    } else {
        guint8 auth_response = tvb_get_guint8(packet->tvb, 0);
        struct session *session = find_session(packet);

        if (session) {
            if (auth_response == AUTH_OK) {
                session->status = AUTH_SUCCESS;
            } else if (auth_response == AUTH_FAILED) {
                session->status = AUTH_FAILURE;
            }
        }
    }
}

void process_postgresql_packet(struct packet *packet) {
    if (packet->is_client) {
        if (packet->length < MIN_CLIENT_PACKET_SIZE) {
            return;
        }

        char *user = extract_user(packet);
        char *database = extract_database(packet);
        struct session *session = find_session(packet->connection_id);

        if (!session) {
            session = create_session(packet->connection_id);
            session->status = CONNECTION_INIT;
        }

        if (packet->type == AUTH_MD5) {
            handle_md5_authentication(session, user, database);
        } else if (packet->type == AUTH_CLEARTEXT) {
            handle_cleartext_authentication(session, user, database);
        }

        free(user);
        free(database);
    } else {
        if (packet->type == AUTH_OK) {
            update_session_status(packet->connection_id, AUTH_SUCCESS);
        } else if (packet->type == AUTH_FAILED) {
            update_session_status(packet->connection_id, AUTH_FAILURE);
        }
    }
}

void process_postgres_packet(struct packet *pkt) {
    if (pkt->from_client) {
        guint32 len = tvb_get_ntohl(pkt->tvb, 0);
        if (len <= 4) {
            return;
        }

        gchar *user = get_user_from_packet(pkt);
        gchar *db = get_database_from_packet(pkt);

        if (!session_exists(pkt)) {
            create_session(pkt);
            init_connection_status(pkt);
        }

        if (g_ascii_strncasecmp("md5", user, 3) == 0) {
            handle_md5_authentication(pkt);
        } else {
            handle_clear_text_authentication(pkt);
        }

        g_free(user);
        g_free(db);
    } else {
        if (tvb_get_guint8(pkt->tvb, 0) == AUTH_OK) {
            update_session_status(pkt, SESSION_AUTHENTICATED);
        } else if (tvb_get_guint8(pkt->tvb, 0) == AUTH_FAILED) {
            update_session_status(pkt, SESSION_FAILED);
        }

        free_session_resources(pkt);
    }
}

void process_postgresql_packet(struct packet* packet) {
    if (packet->is_client) {
        guint32 length;
        const guint8* data = packet->data;

        if (data == NULL || packet->length < 4) {
            return;
        }

        length = tvb_get_ntohl(data);
        if (packet->length < length) {
            return;
        }

        struct session* session = find_session(packet->session_id);
        if (session == NULL) {
            session = create_session(packet->session_id);
            session->status = CONNECTION_STARTED;
        }

        if (data[4] == 'p') {
            const char* user = tvb_get_string_enc(data + 5, data + 5, packet->length - 5, ENC_ASCII);
            const char* database = tvb_get_string_enc(data + 5 + strlen(user) + 1, data + 5 + strlen(user) + 1, packet->length - (5 + strlen(user) + 1), ENC_ASCII);

            session->user = user;
            session->database = database;

            g_free((gchar*)user);
            g_free((gchar*)database);
        } else if (data[4] == 'p') {
            const char* password = tvb_get_string_enc(data + 5, data + 5, packet->length - 5, ENC_ASCII);

            g_free((gchar*)password);
        } else if (data[4] == 'S') {
            const char* sasl_auth = tvb_get_string_enc(data + 5, data + 5, packet->length - 5, ENC_ASCII);

            g_free((gchar*)sasl_auth);
        }

        session->status = AUTHENTICATION_RECEIVED;
    } else {
        const guint8* data = packet->data;

        if (data[0] == 0) {
            guint32 auth_type = tvb_get_ntohl(data + 1);

            if (auth_type == 5) {
                guint32 salt = tvb_get_ntohl(data + 5);
                struct session* session = find_session(packet->session_id);
                if (session != NULL) {
                    session->salt = salt;
                    session->status = AUTHENTICATION_MD5;
                }
            } else if (auth_type == 0) {
                struct session* session = find_session(packet->session_id);
                if (session != NULL) {
                    session->status = AUTHENTICATION_CLEARTEXT;
                }
            }
        }
    }
}

void process_postgresql_packet(struct packet* packet) {
    if (packet->source == CLIENT) {
        guint32 length = tvb_get_ntohl(packet->tvb, 0);
        if (length < 5) return;

        guint8 msg_type = tvb_get_guint8(packet->tvb, 0);
        switch (msg_type) {
            case 'P':  // Startup or SSLRequest
            {
                char* user = get_user_from_packet(packet);
                char* database = get_database_from_packet(packet);
                struct session* session = session_find_or_create(packet->conversation);
                if (!session->user) {
                    session->user = user;
                    session->database = database;
                    session->status = CONNECTION_STARTED;
                } else {
                    free(user);
                    free(database);
                }
                break;
            }
            case 'p':  // Password message
            {
                char* password = get_password_from_packet(packet);
                struct session* session = session_find(packet->conversation);
                if (session && session->status == CONNECTION_STARTED) {
                    if (tvb_get_guint8(packet->tvb, 1) == 0x04) {
                        // MD5 password
                        session->auth_method = AUTH_MD5;
                    } else {
                        // Clear-text password
                        session->auth_method = AUTH_CLEARTEXT;
                    }
                    session->password = password;
                    session->status = AUTH_PASSWORD_SENT;
                } else {
                    free(password);
                }
                break;
            }
            case 'Q':  // Simple query (sent by client)
            {
                // No special processing needed for now
                break;
            }
            default:
                break;
        }
    } else if (packet->source == SERVER) {
        guint8 msg_type = tvb_get_guint8(packet->tvb, 0);
        switch (msg_type) {
            case 'R':  // Authentication request
            {
                guint32 auth_type = tvb_get_ntohl(packet->tvb, 1);
                struct session* session = session_find(packet->conversation);
                if (session && session->status == AUTH_PASSWORD_SENT) {
                    if (auth_type == 5) {
                        session->auth_method = AUTH_MD5;
                    } else if (auth_type == 0) {
                        session->auth_method = AUTH_CLEARTEXT;
                    }
                    session->status = AUTH_RESPONSE_RECEIVED;
                }
                break;
            }
            case 'K':  // Key data
            {
                // Store key data if needed for later processing
                break;
            }
            default:
                break;
        }
    }
}
